body.query:
query NetworkDatasets($network: ID!, $limit: Int!, $offset: Int!) {
  network(key: $network) {
    constituents(limit: $limit, offset: $offset) {
      limit
      offset
      count
      endOfRecords
      results {
        ...DatasetResult
      }
    }
  }
}

fragment DatasetResult on Dataset {
  key
  title
  excerpt
  type
  publishingOrganizationTitle
}
